114	// newHandler wires the API routes and the SPA static handler onto a mux.
115	func newHandler(root, version string, p providers) (http.Handler, error) {
116		api := &apiServer{root: root, version: version, topo: p.topology, dep: p.deploy}
117		static, err := staticHandler()
118		if err != nil {
119			return nil, err
120		}
121	
122		mux := http.NewServeMux()
123		mux.HandleFunc("GET /api/health", api.health)
124		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
125		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
126		mux.HandleFunc("GET /api/flow", api.flow)
127		mux.HandleFunc("GET /api/topology", api.topologies)
128		mux.HandleFunc("POST /api/topology/refresh", api.refreshTopologies)
129		// The verb carries the meaning rather than a /refresh segment: a {path...}
130		// wildcard has to be the last thing in the pattern. GET serves what has
131		// already been read, POST runs the command again.
132		mux.HandleFunc("GET /api/deploy/{path...}", api.getDeployState)
133		mux.HandleFunc("POST /api/deploy/{path...}", api.refreshDeployState)
134		mux.Handle("/", static)
135		return mux, nil
136	}
