158	// scan splits the workspace's scaffold entries for the API: the integration
159	// blocks to catalog, plus the declared systems keyed by their root directory
160	// (the directory holding a system-host scaffold). Support projects — the host
161	// and its shared contracts library — are infrastructure the system view
162	// already represents, not integrations to list.
163	func (s *apiServer) scan() (blocks []template.ScaffoldEntry, systems map[string]string) {
164		entries, _ := template.ListScaffolds(s.root)
165		systems = map[string]string{}
166		for _, e := range entries {
167			if e.Role == template.RoleSystemHost {
168				systems[filepath.Clean(filepath.Dir(e.Path))] = systemName(e)
169			}
170		}
171		blocks = entries[:0]
172		for _, e := range entries {
173			if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
174				continue
175			}
176			blocks = append(blocks, e)
177		}
178		return blocks, systems
