182	// (the template's `name` value, recorded at `sys create`), falling back to
183	// the host's parent directory name.
184	func systemName(host template.ScaffoldEntry) string {
185		if name, ok := host.Values["name"].(string); ok && name != "" {
186			return name
187		}
188		dir := filepath.Dir(host.Path)
189		if abs, err := filepath.Abs(dir); err == nil {
