195	// summarize derives an entry's tree coordinates from its path and the
196	// declared systems. A sibling system-host makes membership explicit: its
197	// declared name wins over the folder-derived one and applies even directly
198	// under the workspace root (where no folder-derived system exists).
199	// Otherwise the workspace root itself never counts as a system or domain, so
200	// an integration scaffolded at the root has neither and one directly under
201	// the root has a system but no domain. The served Path is made root-relative
202	// so it is a stable, URL-safe identifier regardless of whether the command
203	// was given a relative or absolute root (an absolute path would otherwise
204	// break detail lookups).
205	func (s *apiServer) summarize(e template.ScaffoldEntry, systems map[string]string) integrationSummary {
206		sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
207		sum.Path = s.relPath(e.Path)
208		path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
209		parent := filepath.Dir(path)
210		if declared, ok := systems[parent]; ok && path != root {
211			sum.System = declared
212			if grand := filepath.Dir(parent); parent != root && grand != root {
213				sum.Domain = filepath.Base(grand)
214			}
215			return sum
216		}
217		if path == root || parent == root {
218			return sum
219		}
220		sum.System = filepath.Base(parent)
221		if grand := filepath.Dir(parent); grand != root {
222			sum.Domain = filepath.Base(grand)
223		}
224		return sum
225	}
